// Example: Mask credit card number
function maskCreditCard(text) {
    return text.replace(/\b\d{4}[ -]?\d{4}[ -]?\d{4}[ -]?\d{4}\b/g, match => {
        const lastFour = match.slice(-4);
        return '*'.repeat(match.length - 4) + lastFour;
    });
}

